      "candidate_name": "ATTEMPTS_TO_REPAIR",
      "matched_existing_name": "ATTEMPTS_TO_REPAIR"
    },
    {
      "candidate_name": "INVESTIGATES_FAILURE_CAUSE",
      "matched_existing_name": "INVESTIGATES_BEFORE_REMEDIATION"
    }
  ],
  "new": [
    {
      "name": "SELECTS_ALTERNATIVE_APPROACH",
      "definition": "After an earlier intended approach is observed to be blocked or infeasible in the environment, the agent abandons that approach and adopts a different tool or strategy to pursue the same overall goal.",
      "source_description": "An observation that an intended approach or tool family is blocked, unavailable, or otherwise infeasible in the environment.",
      "target_description": "A subsequent agent action that employs an alternative tool or strategy in place of the abandoned approach."
    },
    {
      "name": "CAPABILITY_PROBE_INFORMS_TOOL_SELECTION",
      "definition": "The result of an environment or tooling probe is used to determine which available capability or tool should be applied in a subsequent action.",
      "source_description": "An observation reporting the availability or configuration of environment capabilities, such as present interpreters, installed packages, or tool versions.",
      "target_description": "A subsequent agent action that leverages a capability revealed by that probe to carry out the task."
    },
    {
      "name": "MONITORS_ASYNCHRONOUS_OPERATION",
      "definition": "A long-running operation launched without waiting by an earlier action is subsequently monitored by a separate action that inspects its output or log to determine progress or outcome.",
      "source_description": "An agent action that launches a long-running operation in the background without waiting for it to finish.",
      "target_description": "A subsequent action that inspects the operation's output or log file to determine whether it has completed and with what result."
    }
  ],
  "uncertain": []
}

